import * as THREE from 'three';
const tex = (() => { const c = document.createElement('canvas'); c.width = c.height = 64; const g = c.getContext('2d');
  const r = g.createRadialGradient(32, 32, 2, 32, 32, 30); r.addColorStop(0, 'rgba(255,255,255,0.9)'); r.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = r; g.fillRect(0, 0, 64, 64); return new THREE.CanvasTexture(c); })();
export const breathEmitter = new THREE.Group(); breathEmitter.userData.tag = 'breath-emitter';   // add to the scene once
export function spawnBreath(camera, rng = Math.random) {           // on the key press, not at boot
  const fwd = camera.getWorldDirection(new THREE.Vector3());
  const origin = camera.getWorldPosition(new THREE.Vector3()).addScaledVector(fwd, 0.5).add(new THREE.Vector3(0, -0.08, 0)); // 0.4-0.6 ahead, mouth height
  const n = 5 + Math.floor(rng() * 11);                             // 5-15 sprites per puff
  for (let i = 0; i < n; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, opacity: 0.3, depthWrite: false, color: 0xdfe8f0 }));
    const size = 0.02 + rng() * 0.06;                               // 0.02-0.08 world units: centimetres, not metres
    s.scale.set(size, size, 1);
    s.position.copy(origin).add(new THREE.Vector3((rng() - 0.5) * 0.06, (rng() - 0.5) * 0.04, (rng() - 0.5) * 0.06));
    s.userData = { tag: 'breath', size, life: 2 + rng(), age: 0, vel: fwd.clone().multiplyScalar(0.12 + rng() * 0.1).add(new THREE.Vector3(0, 0.08, 0)) };
    breathEmitter.add(s);
  }
}
export function tickBreath(dt) {
  for (let i = breathEmitter.children.length - 1; i >= 0; i--) {
    const s = breathEmitter.children[i], u = s.userData; u.age += dt;
    const k = 1 - u.age / u.life;
    if (k <= 0) { breathEmitter.remove(s); s.material.dispose(); continue; }
    s.position.addScaledVector(u.vel, dt);
    s.scale.set(u.size * (0.4 + 0.6 * k), u.size * (0.4 + 0.6 * k), 1);   // shrink while fading over 2-3 s, never grow
    s.material.opacity = 0.3 * k;
  }
}
